              | Prepend<MatchImpl<T[0], H>, SubtractArray<Rest, Tail, R>>
          : T
    : R extends true
      ? never
      : T extends readonly []
        ? never
        : T extends readonly [unknown, ...unknown[]]
          ? T
          : T extends readonly [(infer V)?, ...infer Rest]
            ? [T[0], ...Rest]
            : never;

  // Diagnostic examples must be valid pattern syntax. Fall back to _ when a literal needs escaping.
  type FormatPattern<T> = T extends string
    ? string extends T
      ? "_"
      : T extends `${string}${"'" | '"' | "\\" | "\n" | "\r"}${string}`
        ? "_"
        : `'${T}'`
    : T extends bigint
      ? bigint extends T
        ? "_"
        : `${T}n`
      : T extends number
        ? number extends T
          ? "_"
          : `${T}`
        : T extends boolean | null | undefined
          ? `${T}`
          : T extends readonly unknown[]
            ? `[${FormatTuple<T>}]`
            : "_";

  type FormatTuple<T extends readonly unknown[]> = T extends readonly []
    ? ""
    : T extends readonly [infer H, ...infer R]
      ? `${FormatPattern<H>}${R extends [] ? "" : `, ${FormatTuple<R>}`}`
      : "...";

  type MissingPatternMessage<T> =
    IsAny<T> extends true
      ? 'Add an unguarded v-when="_" to prove coverage.'
      : T extends string
        ? string extends T
          ? "An open string requires an unguarded catch-all."
          : T extends `${string}${"'" | '"' | "\\" | "\n" | "\r"}${string}`
            ? 'Add an unguarded v-when="_".'
            : `Missing v-when="'${T}'".`
        : T extends bigint
          ? bigint extends T
            ? "An open bigint requires an unguarded catch-all."
            : `Missing v-when="${T}n".`
          : T extends number
            ? number extends T
              ? "An open number requires an unguarded catch-all."
              : `Missing v-when="${T}".`
            : T extends boolean | null | undefined
              ? `Missing v-when="${T}".`
              : T extends readonly unknown[]
                ? `Missing v-when="[${FormatTuple<T>}]".`
                : 'Coverage cannot be proven. Add missing structural arms or an unguarded v-when="_".';

  // A nonempty remaining space produces an error mapped to the v-match subject.
  type Exhaustiveness<T> = [T] extends [never]
    ? true
    : {
        "Non-exhaustive v-match": T;
      } & { [K in MissingPatternMessage<T>]: never };
}
